package main

import (
	"context"
	"encoding/json"
	"log/slog"
	"time"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
)

// Playback decision log (tv-playback-unblock D8): ONE INFO line per
// descriptor GET, emitted here in the composition root because this closure
// already holds mode/state/reason — api stays pure delegation and Describe
// stays pure. The line correlates with the request-log middleware's line for
// the same request. INV4: the line never carries a token value or a play URL
// — the reason is data, never credentials.

// The decision-log reason vocabulary beyond stream's descriptor honesty
// constants (those ride the stateReason pass-through verbatim), spelled
// exactly as the spec names them.
const (
	reasonPackaged   = "packaged"
	reasonUnpackaged = "unpackaged"
	reasonCooldown   = "cooldown"
	reasonFailed     = "failed"
)

// playbackDescriptor is the api.Deps.Playback closure body (D-7): pure
// delegation over the stream Service's Describe + a fresh media token, then
// the ONE decision-log line. Read-only by contract: nothing here enqueues or
// writes — the descriptor GET never mutates packaging state.
func playbackDescriptor(ctx context.Context, st *store.Store, mediaSvc *stream.Service, itemID string) (api.Playback, error) {
	row, err := st.GetItem(ctx, itemID)
	if err != nil {
		return api.Playback{}, err // sql.ErrNoRows → 404 at the handler
	}
	var doc map[string]any
	if err := json.Unmarshal(row.Document, &doc); err != nil {
		return api.Playback{}, err
	}
	mode, state, playURL, sections, voiceovers, stateReason := mediaSvc.Describe(itemID, doc)
	token, _ := mediaSvc.Issue(itemID, time.Now()) // cookie-primary delivery
	logPlaybackDecision(itemID, mode, state,
		playbackDecisionReason(mode, state, stateReason, streamCooldowns(ctx, st)[itemID], time.Now()))
	return api.Playback{
		Mode:        mode,
		State:       state,
		PlayURL:     playURL,
		StateReason: stateReason,
		Sections:    sections,
		Voiceovers:  voiceovers,
		Token:       token,
	}, nil
}

// playbackDecisionReason resolves the decision line's reason (D8): an hls
// answer logs `packaged` too — the log reads as a complete decision record,
// not a failure-only one. A direct answer names the first live gate: a
// pack-failed ledger row still gating the item (`cooldown` — retry later),
// else the failed run itself (`failed` — retry now), else the descriptor's
// honesty reason for the not-<video>-native floor (Describe's stateReason),
// else `unpackaged` — a plain floor awaiting or skipping its pack.
func playbackDecisionReason(mode, state, stateReason string, coolUntil, now time.Time) string {
	switch {
	case mode == stream.ModeHls:
		return reasonPackaged
	case coolUntil.After(now):
		return reasonCooldown
	case state == stream.StateFailed:
		return reasonFailed
	case stateReason != "":
		return stateReason
	default:
		return reasonUnpackaged
	}
}

// logPlaybackDecision emits the ONE decision line (D8's pinned shape):
// item, mode, state, reason — never a token value, never a play URL (INV4).
func logPlaybackDecision(itemID, mode, state, reason string) {
	slog.Info("playback: descriptor", "item", itemID, "mode", mode, "state", state, "reason", reason)
}
